```
CREATE TABLE translations (
  id INT(11) NOT NULL AUTO_INCREMENT,
  english_phrase VARCHAR(255) NOT NULL,
  spanish_variation VARCHAR(255) NOT NULL,
  translation VARCHAR(255) NOT NULL,
  PRIMARY KEY (id)
);
