```scala
import scala.util.Random
class Star(val location: String, val brightness: Double, val distance: Double)
object StarNameGenerator {
  val existingNames = Set("Sirius", "Polaris", "Betelgeuse", "Antares") // example set of existing star names

  def generateName(star: Star): String = {
    val prefix = star.location.take(3).toUpperCase
    val suffix = {
      val brightnessChar = if (star.brightness > 5) 'B' else 'D'
      val distanceChar = {
        if (star.distance < 10) 'A'
        else if (star.distance < 100) 'B'
        else 'C'
      }
      s"$brightnessChar$distanceChar"
    }
    val name = s"$prefix-$suffix"
    if (existingNames.contains(name)) {
      generateName(star) // recursively generate new name until it's distinct
    } else {
      existingNames.add(name)
      name
    }
  }
}
// example usage
val star = new Star("Orion", 6.2, 80.5)
val name = StarNameGenerator.generateName(star)
println(name) // prints "ORI-BB"
```
