How can I modify the example Go code to generate a haiku poem about love using XML data as input? 
Here's the XML data:
<haiku>
    <line1>
        <syllables>5</syllables>
        <words>heart beats faster now</words>
    </line1>
    <line2>
        <syllables>7</syllables>
        <words>holding hands, feeling alive</words>
    </line2>
    <line3>
        <syllables>5</syllables>
        <words>love blooms in my soul</words>
    </line3>
</haiku>
And here's the modified code:
package main
import (
    "encoding/xml"
    "fmt"
    "math/rand"
    "strings"
    "time"
)
var (
    line1Words []string
    line2Words []string
    line3Words []string
)
type Haiku struct {
    Line1 struct {
        Syllables int    `xml:"syllables"`
        Words     string `xml:"words"`
    } `xml:"line1"`
    Line2 struct {
        Syllables int    `xml:"syllables"`
        Words     string `xml:"words"`
    } `xml:"line2"`
    Line3 struct {
        Syllables int    `xml:"syllables"`
        Words     string `xml:"words"`
    } `xml:"line3"`
}
func main() {
    rand.Seed(time.Now().UnixNano())
    haikuXML := "<haiku><line1><syllables>5</syllables><words>heart beats faster now</words></line1><line2><syllables>7</syllables><words>holding hands, feeling alive</words></line2><line3><syllables>5</syllables><words>love blooms in my soul</words></line3></haiku>"
    var haiku Haiku
    xml.Unmarshal([]byte(haikuXML), &haiku)
    line1Words = strings.Split(haiku.Line1.Words, " ")
    line2Words = strings.Split(haiku.Line2.Words, " ")
    line3Words = strings.Split(haiku.Line3.Words, " ")
    fmt.Println(generateHaiku())
}
func generateHaiku() string {
    var haiku []string
    // First line
    haiku = append(haiku, generateLine(line1Words, haiku.Line1.Syllables))
    // Second line
    haiku = append(haiku, generateLine(line2Words, haiku.Line2.Syllables))
    // Third line
    haiku = append(haiku, generateLine(line3Words, haiku.Line3.Syllables))
    return strings.Join(haiku, ", ")
}
func generateLine(words []string, syllables int) string {
    var line []string
    for len(line) < syllables {
        index := rand.Intn(len(words))
        word := words[index]
        if len(strings.Join(line, " "))+len(word) <= syllables {
            line = append(line, word)
        }
    }
    return strings.Join(line, " ")
}

