What is the Go code that can determine the position of the largest element in a matrix of integers using binary search?
Here is the matrix: 
[[4, 2, 7], [9, 1, 3], [5, 6, 8]]
And here is the code:
func binarySearch(matrix [][]int, low, high int, isRow bool) int {
    var mid int
    for low < high {
        mid = low + (high-low)/2
        if isRow {
            if matrix[mid][0] < matrix[mid+1][0] {
                low = mid + 1
            } else {
                high = mid
            }
        } else {
            if matrix[0][mid] < matrix[0][mid+1] {
                low = mid + 1
            } else {
                high = mid
            }
        }
    }
    return low
}
func findLargest(matrix [][]int) (int, int) {
    rows := len(matrix)
    cols := len(matrix[0])
    var maxRow, maxCol int
    if rows == 1 {
        for i := 1; i < cols; i++ {
            if matrix[0][i] > matrix[0][maxCol] {
                maxCol = i
            }
        }
        return 0, maxCol
    }
    if cols == 1 {
        for i := 1; i < rows; i++ {
            if matrix[i][0] > matrix[maxRow][0] {
                maxRow = i
            }
        }
        return maxRow, 0
    }
    midRow := rows / 2
    midCol := cols / 2
    if matrix[midRow][midCol] < matrix[midRow][midCol+1] {
        maxCol = binarySearch(matrix, midCol, cols-1, false)
    } else {
        maxCol = binarySearch(matrix, 0, midCol, false)
    }
    if matrix[midRow][maxCol] < matrix[midRow+1][maxCol] {
        maxRow = binarySearch(matrix, midRow, rows-1, true)
    } else {
        maxRow = binarySearch(matrix, 0, midRow, true)
    }
    return maxRow, maxCol
}
posX, posY := findLargest([][]int{{4, 2, 7}, {9, 1, 3}, {5, 6, 8}})
fmt.Printf("Position of the largest element is (%d,%d)\n", posX, posY)

