            if strings.Contains(s.Text(), "Antonyms for") {
                s.Find(".css-15v5mhb").Each(func(i int, s *goquery.Selection) {
                    antonyms = append(antonyms, s.Text())
                })
            }
        })
    }
    return antonyms
