import (
	"fmt"
	"github.com/kniren/gota/dataframe"
	"gonum.org/v1/plot"
	"gonum.org/v1/plot/plotter"
	"gonum.org/v1/plot/vg"
	"log"
)
func main() {
	mydata := dataframe.LoadCSV("mydata.csv")
	myvar := mydata.Col("myvar").Float()
	v := make(plotter.Values, len(myvar))
	for i := range v {
		v[i] = myvar[i]
	}
	p, err := plot.New()
	if err != nil {
		log.Fatal(err)
	}
	h, err := plotter.NewHist(v, 16)
	if err != nil {
		log.Fatal(err)
	}
	p.Add(h)
	p.NominalX("myvar")
	p.Title.Text = "Histogram of My Variable"
	p.X.Label.Text = "My Variable Values"
	p.Y.Label.Text = "Frequency"
	if err := p.Save(4*vg.Inch, 4*vg.Inch, "hist.png"); err != nil {
		log.Fatal(err)
	}
	density := plotter.NewFunction(func(x float64) float64 {
		return mydata.KernelDensity("myvar").PDF(x)
	})
	density.Color = color.RGBA{R: 255, A: 255}
	p.Add(density)
	p.Title.Text = "Density Plot of My Variable"
