class Block {
    var previousHash: String
    var data: String
    var hash: String

    init(previousHash: String, data: String) {
        self.previousHash = previousHash
        self.data = data
        self.hash = "\(previousHash)\(data)".sha256() // Hash function
    }
}
extension String {
    func sha256() -> String {
        // Hash function implementation
    }
}
class Blockchain {
    var chain: [Block] = [Block(previousHash: "0", data: "Genesis Block")]

    func addBlock(data: String) {
        let previousHash = chain.last!.hash
        let block = Block(previousHash: previousHash, data: data)
        chain.append(block)
    }
}
