Here is a Python program that implements merge sort to sort a list of 10,000 integers:
```python
import random
import time
def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)
def merge(left, right):
    result = []
    i, j = 0, 0
    while i < len(left) and j < len(right):
        if left[i] >= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result += left[i:]
    result += right[j:]
    return result
def quick_sort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quick_sort(right) + middle + quick_sort(left)
def sort_list(arr):
    if len(arr) < 1000:
        return quick_sort(arr)
    else:
        return merge_sort(arr)
try:
    input_list = [int(x) for x in input("Enter a list of 10000 integers separated by spaces: ").split()]
    if len(input_list) != 10000:
        raise ValueError("Input list must contain exactly 10000 integers.")
    start_time = time.time()
    sorted_list = sort_list(input_list)
    end_time = time.time()
    print(f"Sorted list in descending order: {sorted_list[::-1]}")
    print(f"Time taken: {end_time - start_time} seconds")
except ValueError as ve:
    print(f"Invalid input: {ve}")
except Exception as e:
    print(f"An error occurred: {e}")
```
The time complexity of merge sort is O(n log n), where n is the number of elements in the list. The time complexity of quicksort is O(n^2) in the worst case, but on average it is O(n log n). Since we switch to quicksort only for input lists of size less than 1000, the worst case time complexity of our program is O(n log n).
Note that we display the sorted list in descending order by using the `[::-1]` slicing syntax.

