func getEquipmentName() -> String {
    let availableEquipment = [
        BaseballEquipment(name: "Catcher's Mitt", purpose: "To catch and secure the ball", material: "Leather"),
        BaseballEquipment(name: "Bat", purpose: "To hit the ball", material: "Wood or Metal"),
        BaseballEquipment(name: "Helmet", purpose: "To protect the head", material: "Plastic and Foam"),
