```javascript
// Import the Natural Language Toolkit library
const nltk = require('nltk');
// Define the sentence to analyze
const sentence = 'The temperature is hot today';
// Use NLTK to tokenize the sentence into individual words
const tokens = nltk.word_tokenize(sentence);
// Use NLTK to tag each word with its part of speech
